const https = require('https');
const fs = require('fs');
const dotenv = require('dotenv');

// Load environment variables from .env.test
const envConfig = dotenv.parse(fs.readFileSync('.env.test'));

// Prepare the JSON payload
const payload = JSON.stringify({
  environmentVariables: envConfig
});

const options = {
  hostname: 'localhost',
  port: 3003,
  path: '/api/doc-export',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': payload.length
  }
};

const req = https.request(options, (res) => {
  let data = '';

  res.on('data', (chunk) => {
    data += chunk;
  });

  res.on('end', () => {
    console.log('Environment variables posted successfully:', data);
  });
});

req.on('error', (error) => {
  console.error('Error posting environment variables:', error.message);
});

req.write(payload);
req.end();

